UPDATE hf_directory_releases SET status='ready' WHERE version='202610220000000000000006' AND (SELECT COUNT(*) FROM hf_directory_genomes WHERE version='202610220000000000000006')=20;
UPDATE bted_collections SET version='202610220000000000000006',source_genome_count=20 WHERE collection='experimental' AND version='202610220000000000000005' AND EXISTS (SELECT 1 FROM hf_directory_releases WHERE version='202610220000000000000006' AND status='ready');
